// Domain event — immutable, past tense, carries context
public record OrderPlaced(
    OrderId orderId,
    CustomerId customerId,
    Money totalAmount,
    Instant occurredOn
) implements DomainEvent {}

// Aggregate raises the event during command handling
public class Order {
    private final List<DomainEvent> domainEvents = new ArrayList<>();

    public void place(List<OrderLine> lines) {
        // enforce invariants...
        this.status = OrderStatus.PLACED;
        domainEvents.add(new OrderPlaced(
            this.id, this.customerId, this.total, Instant.now()));
    }

    public List<DomainEvent> pullDomainEvents() {
        var events = List.copyOf(domainEvents);
        domainEvents.clear();
        return events;
    }
}

// Write side — command goes through aggregate
public class PlaceOrderHandler {
    public void handle(PlaceOrderCommand cmd) {
        var order = Order.place(cmd.customerId(), cmd.lines());
        orderRepository.save(order);         // aggregate persisted
        eventPublisher.publish(order.pullDomainEvents()); // events fired
    }
}

