// Event-sourced aggregate — state derived from events
public class Order {
    private OrderStatus status;
    private List<OrderLine> lines = new ArrayList<>();

    // Reconstitution: apply events to rebuild state
    public void apply(OrderPlaced event) {
        this.status = OrderStatus.PLACED;
        this.lines = event.lines();
    }
    public void apply(OrderCancelled event) {
        this.status = OrderStatus.CANCELLED;
    }

    // Command: raise event, do not mutate state directly
    public OrderPlaced place(List<OrderLine> lines) {
        if (this.status != null) throw new IllegalStateException();
        var event = new OrderPlaced(this.id, lines, Instant.now());
        apply(event);        // update state
        return event;        // caller persists and publishes
    }
}

