// ACL translates legacy model into new bounded context's language
public class LegacyOrderAdapter {
    private final LegacyOrderApiClient legacyClient;

    // Translates legacy representation to new domain type
    public Optional<Order> findLegacyOrder(String legacyOrderId) {
        var legacyDto = legacyClient.getOrder(legacyOrderId);
        if (legacyDto == null) return Optional.empty();

        // Translate legacy numeric status codes to domain enum
        var status = switch (legacyDto.getStatusCode()) {
            case 1 -> OrderStatus.PLACED;
            case 2 -> OrderStatus.CONFIRMED;
            case 3 -> OrderStatus.SHIPPED;
            default -> throw new IllegalArgumentException(
                "Unknown legacy status: " + legacyDto.getStatusCode());
        };
        return Optional.of(new Order(OrderId.of(legacyDto.getId()), status));
    }
}

// Projection handler — consumes domain events, updates read store
@Component
public class OrderSummaryProjection {
    private final OrderSummaryRepository readDb;

    @EventHandler
    public void on(OrderPlaced event) {
        readDb.insert(new OrderSummaryRow(
            event.orderId().value(),
            event.customerId().value(),
            "PLACED",
            event.totalAmount(),
            event.occurredOn()
        ));
    }

    @EventHandler
    public void on(OrderCancelled event) {
        readDb.updateStatus(event.orderId().value(), "CANCELLED");
    }

    @EventHandler
    public void on(OrderShipped event) {
        readDb.updateStatus(event.orderId().value(), "SHIPPED");
    }
}

// Aggregate reconstitution from event stream
public class Order {
    // State fields — built by applying events
    private OrderStatus status;
    private Money total;

    // Factory: reconstitute from event history
    public static Order reconstitute(List<DomainEvent> events) {
        var order = new Order(); // empty shell
        for (var event : events) {
            order.apply(event); // replay each event
        }
        return order;
    }

    // Apply methods mutate state — do NOT raise new events
    private void apply(OrderPlaced event) {
        this.status = OrderStatus.PLACED;
        this.total = event.totalAmount();
    }
    private void apply(OrderCancelled event) {
        this.status = OrderStatus.CANCELLED;
    }
}

// Snapshot-aware repository loading
public Order loadOrder(OrderId id) {
    // 1. Try to load the latest snapshot
    var snapshot = snapshotStore.findLatest(id);

    List<DomainEvent> events;
    Order order;

    if (snapshot.isPresent()) {
        // 2. Deserialize snapshot state
        order = snapshot.get().deserialize();
        // 3. Load only events after the snapshot
        events = eventStore.loadAfter(id, snapshot.get().sequenceNumber());
    } else {
        // 4. No snapshot: replay from the beginning
        order = new Order();
        events = eventStore.loadAll(id);
    }

    // 5. Apply remaining events
    events.forEach(order::apply);
    return order;
}

// Policy implemented as an application-layer event handler
@Component
public class ReserveInventoryOnOrderPlaced {
    private final ReserveInventoryUseCase reserveInventory;

    // Lilac sticky: "Whenever OrderPlaced, then Reserve Inventory"
    @EventHandler
    public void on(OrderPlaced event) {
        reserveInventory.reserve(new ReserveInventoryCommand(
            event.orderId(),
            event.lines().stream()
                .map(l -> new ReservationLine(l.productId(), l.quantity()))
                .toList()
        ));
    }
}

